<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/school_profile.php';

require_login();
if (user_role() !== 'siswa') { http_response_code(403); exit('Halaman ini khusus akun siswa.'); }
$siswaId = user_siswa_id();
if (!$siswaId) { http_response_code(403); exit('Akun siswa belum terhubung ke data siswa.'); }

$tpRows = $pdo->query("SELECT id,nama,aktif FROM tahun_pelajaran ORDER BY id DESC")->fetchAll();
$activeTp = null; foreach ($tpRows as $tp) if ((int)$tp['aktif']===1) { $activeTp=$tp; break; }
$tapelId=(int)($_GET['tapel_id']??($activeTp['id']??($tpRows[0]['id']??0)));
$tapelName='-'; foreach($tpRows as $tp) if((int)$tp['id']===$tapelId) $tapelName=(string)$tp['nama'];

$semStmt=$pdo->prepare("SELECT id,nama FROM semester WHERE tahun_pelajaran_id=? AND aktif=1 ORDER BY id DESC LIMIT 1");$semStmt->execute([$tapelId]);$semester=$semStmt->fetch()?:[];
$semesterId=(int)($semester['id']??0);$semesterName=(string)($semester['nama']??'-');

$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,s.jk,mk.nama kelas_nama FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=? AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.id=? LIMIT 1");$st->execute([$tapelId,$siswaId]);$siswa=$st->fetch();
if(!$siswa){http_response_code(404);exit('Data siswa tidak ditemukan.');}

function p_scalar(PDO $pdo,string $sql,array $params=[],int|float $default=0): int|float { try{$st=$pdo->prepare($sql);$st->execute($params);$v=$st->fetchColumn();return $v===false||$v===null?$default:(is_numeric($v)?$v:$default);}catch(Throwable){return $default;} }
function p_rows(PDO $pdo,string $sql,array $params=[]): array { try{$st=$pdo->prepare($sql);$st->execute($params);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable){return [];} }

$hadir=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi a JOIN sesi_absensi sa ON sa.id=a.sesi_id WHERE a.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NULL AND a.status='H'",[$siswaId,$tapelId]);
$terlambat=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi a JOIN sesi_absensi sa ON sa.id=a.sesi_id WHERE a.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NULL AND a.status='T'",[$siswaId,$tapelId]);
$izin=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi a JOIN sesi_absensi sa ON sa.id=a.sesi_id WHERE a.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NULL AND a.status='I'",[$siswaId,$tapelId]);
$sakit=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi a JOIN sesi_absensi sa ON sa.id=a.sesi_id WHERE a.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NULL AND a.status='S'",[$siswaId,$tapelId]);
$alpa=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi a JOIN sesi_absensi sa ON sa.id=a.sesi_id WHERE a.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NULL AND a.status='A'",[$siswaId,$tapelId]);
$totalStatus=$hadir+$terlambat+$izin+$sakit+$alpa;$hadirPct=$totalStatus?round((($hadir+$terlambat)/$totalStatus)*100):0;

$sholatSudah=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi_sholat ash JOIN sesi_absensi sa ON sa.id=ash.sesi_id WHERE ash.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NOT NULL AND ash.status='SUDAH'",[$siswaId,$tapelId]);
$sholatBerhalangan=(int)p_scalar($pdo,"SELECT COUNT(*) FROM absensi_sholat ash JOIN sesi_absensi sa ON sa.id=ash.sesi_id WHERE ash.siswa_id=? AND sa.tahun_pelajaran_id=? AND sa.jenis_sholat_id IS NOT NULL AND ash.status='BERHALANGAN'",[$siswaId,$tapelId]);
$sholatSesi=(int)p_scalar($pdo,"SELECT COUNT(*) FROM sesi_absensi WHERE tahun_pelajaran_id=? AND semester_id=? AND jenis_sholat_id IS NOT NULL AND status_sesi IN ('OPEN','CLOSED')",[$tapelId,$semesterId]);
$sholatTercatat=$sholatSudah+$sholatBerhalangan;$sholatBelum=max(0,$sholatSesi-$sholatTercatat);$sholatPct=$sholatTercatat?round(($sholatSudah/$sholatTercatat)*100):0;

$izinRows=p_rows($pdo,"SELECT tanggal,jenis,alasan,keterangan,status FROM izin_siswa WHERE siswa_id=? AND tahun_pelajaran_id=? ORDER BY tanggal DESC,id DESC LIMIT 5",[$siswaId,$tapelId]);
$extraRows=p_rows($pdo,"SELECT e.id,e.nama,ea.status FROM ekstra_anggota ea JOIN ekstrakurikuler e ON e.id=ea.ekstrakurikuler_id WHERE ea.siswa_id=? AND ea.tahun_pelajaran_id=? ORDER BY e.nama",[$siswaId,$tapelId]);
$extraCount=count(array_filter($extraRows,fn($r)=>($r['status']??'aktif')==='aktif'));
$extraAttend=(int)p_scalar($pdo,"SELECT COUNT(*) FROM ekstra_absensi ea JOIN ekstra_sesi es ON es.id=ea.sesi_id WHERE ea.siswa_id=? AND es.tahun_pelajaran_id=? AND ea.status IN ('hadir','terlambat')",[$siswaId,$tapelId]);

$libBorrowed=p_rows($pdo,"SELECT pp.nomor_transaksi,pp.tanggal_pinjam,pp.tanggal_jatuh_tempo,pp.status,pb.judul,pd.status detail_status,pd.tanggal_kembali,pd.denda FROM perpustakaan_peminjaman pp JOIN perpustakaan_anggota pa ON pa.id=pp.anggota_id JOIN perpustakaan_detail_peminjaman pd ON pd.peminjaman_id=pp.id JOIN perpustakaan_buku pb ON pb.id=pd.buku_id WHERE pa.siswa_id=? AND pp.status IN ('dipinjam','sebagian_kembali','terlambat') AND pd.status='dipinjam' ORDER BY pp.tanggal_pinjam DESC,pp.id DESC",[$siswaId]);
$libHistory=p_rows($pdo,"SELECT pp.nomor_transaksi,pp.tanggal_pinjam,pp.tanggal_selesai,pp.status,pb.judul,pd.status detail_status,pd.tanggal_kembali,pd.denda FROM perpustakaan_peminjaman pp JOIN perpustakaan_anggota pa ON pa.id=pp.anggota_id JOIN perpustakaan_detail_peminjaman pd ON pd.peminjaman_id=pp.id JOIN perpustakaan_buku pb ON pb.id=pd.buku_id WHERE pa.siswa_id=? ORDER BY pp.tanggal_pinjam DESC,pp.id DESC LIMIT 10",[$siswaId]);

$uksRows=p_rows($pdo,"SELECT tanggal,waktu,status,jenis_layanan,keluhan,hasil_pemeriksaan,tindakan,obat,rujukan,catatan FROM uks_kunjungan WHERE siswa_id=? AND tahun_pelajaran_id=? ORDER BY tanggal DESC,waktu DESC,id DESC LIMIT 10",[$siswaId,$tapelId]);
$pelanggaranCount=(int)p_scalar($pdo,"SELECT COUNT(*) FROM pelanggaran_siswa WHERE siswa_id=? AND tahun_pelajaran_id=?",[$siswaId,$tapelId]);
$pelanggaranPoin=(int)p_scalar($pdo,"SELECT COALESCE(SUM(poin),0) FROM pelanggaran_siswa WHERE siswa_id=? AND tahun_pelajaran_id=?",[$siswaId,$tapelId]);
$pembinaanCount=(int)p_scalar($pdo,"SELECT COUNT(*) FROM pembinaan_siswa WHERE siswa_id=? AND tahun_pelajaran_id=?",[$siswaId,$tapelId]);
$catatanRows=p_rows($pdo,"SELECT tanggal,jenis,status,hasil,tindak_lanjut FROM pembinaan_siswa WHERE siswa_id=? AND tahun_pelajaran_id=? ORDER BY tanggal DESC,id DESC LIMIT 5",[$siswaId,$tapelId]);
$bkCount=(int)p_scalar($pdo,"SELECT COUNT(*) FROM konsultasi_bk WHERE siswa_id=? AND tahun_pelajaran_id=?",[$siswaId,$tapelId]);
$bkRows=p_rows($pdo,"SELECT tanggal,waktu,jenis,topik,hasil,kesepakatan,tindak_lanjut,status,melibatkan_ortu FROM konsultasi_bk WHERE siswa_id=? AND tahun_pelajaran_id=? ORDER BY tanggal DESC,waktu DESC,id DESC LIMIT 5",[$siswaId,$tapelId]);
$pelRows=p_rows($pdo,"SELECT ps.tanggal,ps.waktu,jp.kode,jp.nama jenis_pelanggaran,ps.poin,ps.tindakan,ps.status,ps.keterangan FROM pelanggaran_siswa ps JOIN jenis_pelanggaran jp ON jp.id=ps.jenis_pelanggaran_id WHERE ps.siswa_id=? AND ps.tahun_pelajaran_id=? ORDER BY ps.tanggal DESC,ps.waktu DESC,ps.id DESC LIMIT 5",[$siswaId,$tapelId]);
$homeVisitCount=(int)p_scalar($pdo,"SELECT COUNT(*) FROM home_visit WHERE siswa_id=? AND tahun_pelajaran_id=?",[$siswaId,$tapelId]);
$homeVisitRows=p_rows($pdo,"SELECT tanggal_rencana,tanggal_pelaksanaan,waktu,alasan,tujuan,hasil,tindak_lanjut,status FROM home_visit WHERE siswa_id=? AND tahun_pelajaran_id=? ORDER BY COALESCE(tanggal_pelaksanaan,tanggal_rencana) DESC,id DESC LIMIT 5",[$siswaId,$tapelId]);

$unsupported=[
 ['icon'=>'cash-coin','title'=>'Pembayaran','text'=>'Belum ada modul pembayaran pada sumber data aplikasi saat ini.','tone'=>'orange'],
 ['icon'=>'journal-bookmark-fill','title'=>'Nilai','text'=>'Belum ada sumber data nilai yang terhubung pada aplikasi saat ini.','tone'=>'violet'],
 ['icon'=>'megaphone-fill','title'=>'Informasi Wali Kelas','text'=>'Belum ada sumber data pengumuman wali kelas yang terhubung pada aplikasi saat ini.','tone'=>'cyan'],
];
